{
  // ============================================================================
  //  POST /payments/pos/pay  — ONE endpoint for every POS payment type.
  //  Send ONLY the fields for the payment_type you pick. Amounts must equal the
  //  order total. The chosen payment_type is stored on the order (Order.pos_payment_type).
  // ============================================================================

  "order_code": "{{order_code}}",          // Required - the order to pay
  "payment_type": "bank_transfer",                  // Required - see the 5 options below

  // --- payment_type: "cash" -------------------------------------------------
  //   "cash_amount": 31.79                 // Optional (defaults to order total). Instant paid.

  // --- payment_type: "bank_transfer" ----------------------------------------
    "bank_amount": 64.78,                // Optional (defaults to order total). Instant paid.
    "bank_reference": "TXN-12345"        // Optional - stored on the payment

  // --- payment_type: "stripe_terminal" (card present) -----------------------
  //   "reader_id": {{reader_id}},          // Required - your registered reader
  //   "terminal_amount": 31.79             // Optional (defaults to order total)
  //   >>> response.requires_action=true. Then poll /terminal/payment-status/:ref
  //       and POST /terminal/capture to finish. Order paid on capture.

  // --- payment_type: "cash_bank_transfer" (split) ---------------------------
  //   "cash_amount": 15.90,                // Required
  //   "bank_amount": 15.89,                // Required (cash + bank = total)
  //   "bank_reference": "TXN-12345"        // Optional

  // --- payment_type: "cash_stripe_terminal" (split) -------------------------
  //   "cash_amount": 15.90,                // Required (instant paid)
  //   "terminal_amount": 15.89,            // Required (cash + terminal = total)
  //   "reader_id": {{reader_id}}           // Required
  //   >>> cash part paid now; terminal part = poll + capture.

  // ============================================================================
  //  RESPONSE (same shape for all):
  //  {
  //    order_code, payment_type, pos_payment_type, total_amount,
  //    paid_amount,            // sum of parts already paid
  //    fully_paid,            // true once everything is captured
  //    requires_action,       // true = a terminal part still needs poll + capture
  //    parts: [ { method, amount, status, payment_reference, ... } ],
  //    terminal: { payment_reference, payment_intent_id, reader_id, next_steps } | null
  //  }
  // ============================================================================
}

{
  "order_code": "{{order_code}}",       // Required
  "payment_type": "cash",               // Required
  "cash_amount": 31.79                  // Optional - defaults to the order total
}

// Instant: order becomes paid + accepted. requires_action = false.

{
  "order_code": "{{order_code}}",       // Required
  "payment_type": "bank_transfer",      // Required
  "bank_amount": 31.79,                 // Optional - defaults to the order total
  "bank_reference": "TXN-12345"         // Optional - stored on the payment
}

{
  "order_code": "{{order_code}}",       // Required
  "payment_type": "stripe_terminal",    // Required
  "reader_id": {{reader_id}},           // Required - your registered reader id
  "terminal_amount": 31.79              // Optional - defaults to the order total
}

// requires_action = true. Response.terminal has the payment_reference.
// Then: poll GET /terminal/payment-status/:ref until action_required=false,
// then POST /terminal/capture to finalise. Order becomes paid on capture.

{
  "order_code": "{{order_code}}",       // Required
  "payment_type": "cash_bank_transfer", // Required
  "cash_amount": 15.90,                 // Required - must sum with bank_amount to the total
  "bank_amount": 15.89,                 // Required
  "bank_reference": "TXN-12345"         // Optional
}

// Both parts recorded paid; order becomes paid + accepted immediately.

{
  "order_code": "{{order_code}}",         // Required
  "payment_type": "cash_stripe_terminal", // Required
  "cash_amount": 15.90,                   // Required
  "terminal_amount": 15.89,               // Required - must sum with cash to the total
  "reader_id": {{reader_id}}              // Required
}

// Cash part is paid immediately; the terminal part is pending.
// requires_action = true -> poll payment-status then capture. Order becomes
// fully paid once the terminal part is captured (paid_amount is summed).

{
  "payment_reference": "{{payment_reference}}"   // Required - from the pay response / poll
}

// Call once the poll says it is ready. Finalises the charge and marks the
// order paid (paid_amount is the sum of all paid parts, so splits work).

{
  "reader_id": {{reader_id}}             // Required
}

// Cancel the in-progress collection on the reader (e.g. customer walked away).
